REPLACE INTO `users` (`id`, `org_id`, `email`, `full_name`, `role`, `preferred_language`, `created_at`) VALUES ('usr_03', 'org_vn_fdi_01', 'minh.tran@techvina.vn', 'Trần Quốc Minh (Senior Recruiter)', 'recruiter', 'vi', '2026-10-17T14:01:09Z');
REPLACE INTO `jobs` (`id`, `org_id`, `title`, `department`, `location`, `employment_type`, `salary_range`, `language`, `report_languages`, `status`, `jd_text`, `must_have_skills`, `nice_to_have_skills`, `min_experience_years`, `rubric_config`, `scoring_weights`, `interview_questions`, `blind_mode`, `created_at`) VALUES ('job_01', 'org_vn_fdi_01', '[Quản lý Cao cấp] Giám đốc Kỹ thuật & Trí tuệ Nhân tạo (VP of Engineering & AI)', 'Công nghệ Thông tin & Trí tuệ Nhân tạo (IT / AI)', 'TP. Hồ Chí Minh / Hà Nội', 'Full-time (Quản lý)', '85 - 140 Triệu VNĐ', 'vi', '["vi", "en", "ja", "ko", "zh", "th", "lo", "km"]', 'open', 'Điều hành toàn bộ khối Kỹ thuật & AI gồm 120 kỹ sư; hoạch định kiến trúc Microservices, nền tảng LLM/RAG đa ngôn ngữ và chịu trách nhiệm SLA 99.99%, tối ưu chi phí hạ tầng Cloud/GPU cho tập đoàn.', '["AI / LLM / RAG", "Python", "FastAPI", "Docker / Kubernetes", "PostgreSQL / SQL"]', '["English Ielts/Toeic"]', 8.0, '[{"criterion": "Chiến lược Kiến trúc & Quy mô Hệ thống", "weight": 0.35}, {"criterion": "Quản trị Đội ngũ Kỹ thuật Cấp cao", "weight": 0.35}, {"criterion": "Bảo mật Dữ liệu & Tuân thủ", "weight": 0.3}]', '{"must_have": 0.4, "semantic": 0.35, "experience": 0.25}', '[{"competency": "Chiến lược Kiến trúc & Quy mô Hệ thống", "question": "Anh/Chị đã từng thiết kế và điều hành kiến trúc AI/Cloud phục vụ hàng triệu người dùng với SLA 99.99% như thế nào? Hãy nêu số liệu tối ưu chi phí thực tế."}, {"competency": "Quản trị Đội ngũ Kỹ thuật Cấp cao", "question": "Cách Anh/Chị xây dựng KPIs (DORA metrics) và tổ chức các phòng ban Engineering, Data, MLOps trên 100 nhân sự để rút ngắn Time-to-Market?"}, {"competency": "Bảo mật Dữ liệu & Tuân thủ", "question": "Anh/Chị triển khai cơ chế chống Prompt Injection, bảo vệ dữ liệu cá nhân theo Nghị định 13/2023/NĐ-CP và ISO 27001 ra sao?"}]', 0, '2026-10-17T14:01:09Z');
REPLACE INTO `jobs` (`id`, `org_id`, `title`, `department`, `location`, `employment_type`, `salary_range`, `language`, `report_languages`, `status`, `jd_text`, `must_have_skills`, `nice_to_have_skills`, `min_experience_years`, `rubric_config`, `scoring_weights`, `interview_questions`, `blind_mode`, `created_at`) VALUES ('job_02', 'org_vn_fdi_01', '[Quản lý Cấp trung] Trưởng phòng Phát triển Phần mềm & Nền tảng Số (Engineering Manager)', 'Công nghệ Thông tin & Trí tuệ Nhân tạo (IT / AI)', 'Hà Nội', 'Full-time (Quản lý)', '50 - 78 Triệu VNĐ', 'vi', '["vi", "en", "ja", "ko", "zh", "th", "lo", "km"]', 'open', 'Quản lý trực tiếp 3 Squad phát triển sản phẩm SaaS/FinTech (25-35 kỹ sư); kiểm soát chất lượng mã nguồn, CI/CD, kiến trúc cơ sở dữ liệu và tiến độ bàn giao Sprint.', '["Python", "FastAPI", "React / Next.js", "PostgreSQL / SQL", "Docker / Kubernetes"]', '["AI / LLM / RAG"]', 5.0, '[{"criterion": "Quản lý Dự án Agile & Chất lượng Code", "weight": 0.35}, {"criterion": "Tối ưu Hiệu năng Hệ thống", "weight": 0.35}, {"criterion": "Phát triển Nhân tài Kỹ thuật", "weight": 0.3}]', '{"must_have": 0.4, "semantic": 0.35, "experience": 0.25}', '[{"competency": "Quản lý Dự án Agile & Chất lượng Code", "question": "Anh/Chị xử lý nợ kỹ thuật (Technical Debt) và đảm bảo tốc độ phát triển tính năng của 3 Squad cùng lúc như thế nào?"}, {"competency": "Tối ưu Hiệu năng Hệ thống", "question": "Hãy chia sẻ một tình huống hệ thống bị nghẽn cổ chai ở tầng Database/API và cách Anh/Chị chỉ đạo đội ngũ xử lý triệt để."}, {"competency": "Phát triển Nhân tài Kỹ thuật", "question": "Anh/Chị đánh giá năng lực và giữ chân các Senior Engineer chủ chốt trong giai đoạn dự án cao điểm bằng phương pháp nào?"}]', 0, '2026-10-17T14:01:09Z');
REPLACE INTO `jobs` (`id`, `org_id`, `title`, `department`, `location`, `employment_type`, `salary_range`, `language`, `report_languages`, `status`, `jd_text`, `must_have_skills`, `nice_to_have_skills`, `min_experience_years`, `rubric_config`, `scoring_weights`, `interview_questions`, `blind_mode`, `created_at`) VALUES ('job_03', 'org_vn_fdi_01', '[Quản lý Cao cấp] Giám đốc Chuyển đổi Số & Quản trị Dữ liệu (Head of Digital Transformation & Data)', 'Công nghệ Thông tin & Trí tuệ Nhân tạo (IT / AI)', 'TP. Hồ Chí Minh', 'Full-time (Quản lý)', '75 - 120 Triệu VNĐ', 'vi', '["vi", "en", "ja", "ko", "zh", "th", "lo", "km"]', 'open', 'Chủ trì lộ trình chuyển đổi số toàn tập đoàn, xây dựng Enterprise Data Lakehouse, hệ thống BI/AI tự động hóa quy trình vận hành ERP/CRM và báo cáo trực tiếp cho Tổng Giám đốc.', '["AI / LLM / RAG", "PostgreSQL / SQL", "Bridge SE / BA", "English Ielts/Toeic"]', '["Python"]', 7.0, '[{"criterion": "Hoạch định Lộ trình Chuyển đổi Số", "weight": 0.35}, {"criterion": "Quản trị Thay đổi Liên phòng ban", "weight": 0.35}, {"criterion": "Quản trị & Khai thác Dữ liệu Lớn", "weight": 0.3}]', '{"must_have": 0.4, "semantic": 0.35, "experience": 0.25}', '[{"competency": "Hoạch định Lộ trình Chuyển đổi Số", "question": "Anh/Chị đo lường chỉ số ROI thực tế của các dự án Chuyển đổi Số và Data Warehouse ở quy mô tập đoàn như thế nào?"}, {"competency": "Quản trị Thay đổi Liên phòng ban", "question": "Khi triển khai ERP/AI mới gặp sự kháng cự từ các khối vận hành truyền thống, Anh/Chị giải quyết và thuyết phục các bên ra sao?"}, {"competency": "Quản trị & Khai thác Dữ liệu Lớn", "question": "Anh/Chị thiết lập khung Data Governance và chất lượng dữ liệu phục vụ báo cáo điều hành thời gian thực như thế nào?"}]', 0, '2026-10-17T14:01:09Z');
REPLACE INTO `jobs` (`id`, `org_id`, `title`, `department`, `location`, `employment_type`, `salary_range`, `language`, `report_languages`, `status`, `jd_text`, `must_have_skills`, `nice_to_have_skills`, `min_experience_years`, `rubric_config`, `scoring_weights`, `interview_questions`, `blind_mode`, `created_at`) VALUES ('job_04', 'org_vn_fdi_01', '[Quản lý Cao cấp] Giám đốc Khối Quản trị Rủi ro Tín dụng & Basel III (Head of Credit Risk)', 'Tài chính - Ngân hàng - Bảo hiểm (Banking & Finance)', 'Hà Nội', 'Full-time (Quản lý)', '90 - 150 Triệu VNĐ', 'vi', '["vi", "en", "ja", "ko", "zh", "th", "lo", "km"]', 'open', 'Chỉ đạo toàn diện công tác quản trị rủi ro tín dụng, rủi ro thị trường và rủi ro hoạt động theo chuẩn Basel III & quy định Ngân hàng Nhà nước; phê duyệt mô hình AI Credit Scoring và kiểm soát tỷ lệ nợ xấu (NPL) dưới 1.5%.', '["PostgreSQL / SQL", "AI / LLM / RAG", "English Ielts/Toeic", "Bridge SE / BA"]', '["Python"]', 8.0, '[{"criterion": "Quản trị Rủi ro Chuẩn Basel III", "weight": 0.35}, {"criterion": "Phân tích Danh mục & Stress Testing", "weight": 0.35}, {"criterion": "Lãnh đạo Hội đồng Tín dụng", "weight": 0.3}]', '{"must_have": 0.4, "semantic": 0.35, "experience": 0.25}', '[{"competency": "Quản trị Rủi ro Chuẩn Basel III", "question": "Anh/Chị đã thiết lập khung khẩu vị rủi ro và mô hình chấm điểm tín dụng tự động giúp kiểm soát nợ xấu (NPL) dưới ngưỡng mục tiêu như thế nào?"}, {"competency": "Phân tích Danh mục & Stress Testing", "question": "Cách Anh/Chị điều hành kịch bản kiểm tra sức chịu đựng (Stress Test) trước biến động lãi suất và tỷ giá vĩ mô tại Việt Nam?"}, {"competency": "Lãnh đạo Hội đồng Tín dụng", "question": "Anh/Chị cân bằng giữa áp lực tăng trưởng dư nợ của khối Kinh doanh và kỷ luật an toàn vốn của khối Rủi ro ra sao?"}]', 0, '2026-10-17T14:01:09Z');
REPLACE INTO `jobs` (`id`, `org_id`, `title`, `department`, `location`, `employment_type`, `salary_range`, `language`, `report_languages`, `status`, `jd_text`, `must_have_skills`, `nice_to_have_skills`, `min_experience_years`, `rubric_config`, `scoring_weights`, `interview_questions`, `blind_mode`, `created_at`) VALUES ('job_05', 'org_vn_fdi_01', '[Quản lý Cấp trung] Trưởng phòng Khách hàng Doanh nghiệp Lớn & FDI (Corporate Banking Manager)', 'Tài chính - Ngân hàng - Bảo hiểm (Banking & Finance)', 'TP. Hồ Chí Minh', 'Full-time (Quản lý)', '50 - 80 Triệu VNĐ', 'vi', '["vi", "en", "ja", "ko", "zh", "th", "lo", "km"]', 'open', 'Phát triển và quản lý danh mục khách hàng doanh nghiệp FDI (Nhật Bản, Hàn Quốc, Âu Mỹ) và tập đoàn nội địa; thúc đẩy doanh số tín dụng thương mại, tài trợ chuỗi cung ứng, bảo lãnh và CASA.', '["B2B Sales / Telesales", "English Ielts/Toeic", "Japanese N2/N3", "Korean TOPIK"]', '["Chinese HSK"]', 5.0, '[{"criterion": "Phát triển Danh mục Khách hàng FDI", "weight": 0.35}, {"criterion": "Thẩm định Tài chính Doanh nghiệp", "weight": 0.35}, {"criterion": "Huấn luyện Đội ngũ RM", "weight": 0.3}]', '{"must_have": 0.4, "semantic": 0.35, "experience": 0.25}', '[{"competency": "Phát triển Danh mục Khách hàng FDI", "question": "Anh/Chị đã xây dựng mạng lưới khách hàng FDI và tăng quy mô huy động CASA/dư nợ tín dụng doanh nghiệp đạt bao nhiêu tỷ VNĐ trong 2 năm qua?"}, {"competency": "Thẩm định Tài chính Doanh nghiệp", "question": "Khi cấu trúc gói tài trợ vốn lưu động và bảo lãnh cho doanh nghiệp sản xuất xuất khẩu, Anh/Chị chú trọng những chỉ số dòng tiền nào nhất?"}, {"competency": "Huấn luyện Đội ngũ RM", "question": "Cách Anh/Chị kèm cặp đội ngũ 15 Chuyên viên Quan hệ Khách hàng (RM) chốt các hợp đồng tài chính phức tạp?"}]', 0, '2026-10-17T14:01:09Z');
REPLACE INTO `jobs` (`id`, `org_id`, `title`, `department`, `location`, `employment_type`, `salary_range`, `language`, `report_languages`, `status`, `jd_text`, `must_have_skills`, `nice_to_have_skills`, `min_experience_years`, `rubric_config`, `scoring_weights`, `interview_questions`, `blind_mode`, `created_at`) VALUES ('job_06', 'org_vn_fdi_01', '[Quản lý Cao cấp] Giám đốc Đầu tư & Mua bán Sáp nhập (Investment & M&A Director)', 'Tài chính - Ngân hàng - Bảo hiểm (Banking & Finance)', 'TP. Hồ Chí Minh', 'Full-time (Quản lý)', '85 - 140 Triệu VNĐ', 'vi', '["vi", "en", "ja", "ko", "zh", "th", "lo", "km"]', 'open', 'Dẫn dắt hoạt động thẩm định đầu tư (Due Diligence), định giá doanh nghiệp (DCF, LBO), cấu trúc thương vụ M&A và huy động vốn quốc tế quy mô từ 10 - 100 triệu USD.', '["English Ielts/Toeic", "Bridge SE / BA", "B2B Sales / Telesales"]', '["PostgreSQL / SQL"]', 7.0, '[{"criterion": "Cấu trúc Thương vụ M&A & Định giá", "weight": 0.35}, {"criterion": "Quản trị Danh mục Sau Đầu tư", "weight": 0.35}, {"criterion": "Đàm phán với Quỹ Đầu tư Quốc tế", "weight": 0.3}]', '{"must_have": 0.4, "semantic": 0.35, "experience": 0.25}', '[{"competency": "Cấu trúc Thương vụ M&A & Định giá", "question": "Hãy trình bày một thương vụ M&A hoặc huy động vốn lớn nhất mà Anh/Chị từng dẫn dắt từ giai đoạn Due Diligence đến khi ký kết SHA/SPA."}, {"competency": "Quản trị Danh mục Sau Đầu tư", "question": "Sau khi hoàn tất giải ngân đầu tư, Anh/Chị tham gia tái cấu trúc tài chính để nâng biên lợi nhuận EBITDA của công ty mục tiêu như thế nào?"}, {"competency": "Đàm phán với Quỹ Đầu tư Quốc tế", "question": "Kinh nghiệm của Anh/Chị khi đàm phán điều khoản bảo vệ nhà đầu tư và cơ chế thoái vốn với các quỹ PE/VC nước ngoài?"}]', 0, '2026-10-17T14:01:09Z');
REPLACE INTO `jobs` (`id`, `org_id`, `title`, `department`, `location`, `employment_type`, `salary_range`, `language`, `report_languages`, `status`, `jd_text`, `must_have_skills`, `nice_to_have_skills`, `min_experience_years`, `rubric_config`, `scoring_weights`, `interview_questions`, `blind_mode`, `created_at`) VALUES ('job_07', 'org_vn_fdi_01', '[Quản lý Cao cấp] Giám đốc Nhà máy Sản xuất Điện tử FDI (Plant Director / General Manager)', 'Sản xuất Công nghiệp & FDI Điện tử (Manufacturing & FDI)', 'Bắc Ninh / Hải Phòng', 'Full-time (Quản lý)', '80 - 140 Triệu VNĐ', 'vi', '["vi", "en", "ja", "ko", "zh", "th", "lo", "km"]', 'open', 'Điều hành toàn diện nhà máy sản xuất linh kiện điện tử công nghệ cao quy mô 2.500 công nhân; chịu trách nhiệm chỉ số OEE, năng suất dây chuyền SMT, an toàn EHS, chi phí sản xuất và giao hàng đúng hạn 99.8%.', '["Manufacturing / QA-QC", "QA / Testing", "Korean TOPIK", "English Ielts/Toeic"]', '["Japanese N2/N3"]', 8.0, '[{"criterion": "Điều hành Vận hành Nhà máy Quy mô Lớn", "weight": 0.35}, {"criterion": "Quản trị Chi phí Sản xuất & P&L", "weight": 0.35}, {"criterion": "Văn hóa An toàn & Quan hệ Lao động", "weight": 0.3}]', '{"must_have": 0.4, "semantic": 0.35, "experience": 0.25}', '[{"competency": "Điều hành Vận hành Nhà máy Quy mô Lớn", "question": "Anh/Chị đã từng nâng chỉ số OEE và giảm tỷ lệ phế phẩm (Scrap Rate) tại nhà máy trên 1.000 lao động bằng những giải pháp cụ thể nào?"}, {"competency": "Quản trị Chi phí Sản xuất & P&L", "question": "Cách Anh/Chị kiểm soát định mức tiêu hao nguyên vật liệu, năng lượng và tối ưu chi phí nhân công trực tiếp trên mỗi đơn vị sản phẩm?"}, {"competency": "Văn hóa An toàn & Quan hệ Lao động", "question": "Anh/Chị làm thế nào để duy trì tỷ lệ nghỉ việc của công nhân dưới 3%/tháng và đạt 0 tai nạn lao động (Zero LTI)?"}]', 0, '2026-10-17T14:01:09Z');
REPLACE INTO `jobs` (`id`, `org_id`, `title`, `department`, `location`, `employment_type`, `salary_range`, `language`, `report_languages`, `status`, `jd_text`, `must_have_skills`, `nice_to_have_skills`, `min_experience_years`, `rubric_config`, `scoring_weights`, `interview_questions`, `blind_mode`, `created_at`) VALUES ('job_08', 'org_vn_fdi_01', '[Quản lý Cấp trung] Trưởng phòng Quản lý Chất lượng Toàn diện (QA/QC & ISO Senior Manager)', 'Sản xuất Công nghiệp & FDI Điện tử (Manufacturing & FDI)', 'Bình Dương / Đồng Nai', 'Full-time (Quản lý)', '42 - 68 Triệu VNĐ', 'vi', '["vi", "en", "ja", "ko", "zh", "th", "lo", "km"]', 'open', 'Quản lý hệ thống chất lượng IQC, IPQC, OQC theo tiêu chuẩn IATF 16949 & ISO 9001; chủ trì giải quyết khiếu nại khách hàng toàn cầu theo phương pháp 8D, FMEA, SPC và 6 Sigma.', '["Manufacturing / QA-QC", "QA / Testing", "Japanese N2/N3", "English Ielts/Toeic"]', '["Korean TOPIK"]', 5.0, '[{"criterion": "Hệ thống Quản trị Chất lượng IATF/ISO", "weight": 0.35}, {"criterion": "Đối ứng Kiểm toán Khách hàng Quốc tế", "weight": 0.35}, {"criterion": "Quản lý Chất lượng Nhà cung cấp (SQE)", "weight": 0.3}]', '{"must_have": 0.4, "semantic": 0.35, "experience": 0.25}', '[{"competency": "Hệ thống Quản trị Chất lượng IATF/ISO", "question": "Anh/Chị đã áp dụng công cụ 8D, PFMEA và SPC để giảm tỷ lệ lỗi PPM trên dây chuyền sản xuất xuống mức nào?"}, {"competency": "Đối ứng Kiểm toán Khách hàng Quốc tế", "question": "Kinh nghiệm của Anh/Chị khi chủ trì các đợt Audit khắt khe từ khách hàng Nhật Bản, Hàn Quốc và Âu Mỹ?"}, {"competency": "Quản lý Chất lượng Nhà cung cấp (SQE)", "question": "Khi lô linh kiện đầu vào gặp lỗi hàng loạt ảnh hưởng tiến độ xuất hàng, Anh/Chị xử lý với nhà cung cấp và bộ phận Sản xuất ra sao?"}]', 0, '2026-10-17T14:01:09Z');
REPLACE INTO `jobs` (`id`, `org_id`, `title`, `department`, `location`, `employment_type`, `salary_range`, `language`, `report_languages`, `status`, `jd_text`, `must_have_skills`, `nice_to_have_skills`, `min_experience_years`, `rubric_config`, `scoring_weights`, `interview_questions`, `blind_mode`, `created_at`) VALUES ('job_09', 'org_vn_fdi_01', '[Quản lý Cấp trung] Trưởng phòng Kỹ thuật Tự động hóa & Cải tiến Lean (Automation & Lean Manager)', 'Sản xuất Công nghiệp & FDI Điện tử (Manufacturing & FDI)', 'Bắc Giang / Thái Nguyên', 'Full-time (Quản lý)', '45 - 70 Triệu VNĐ', 'vi', '["vi", "en", "ja", "ko", "zh", "th", "lo", "km"]', 'open', 'Triển khai các dự án tự động hóa dây chuyền (PLC, Robot công nghiệp, hệ thống thị giác máy tính AOI) và chương trình cải tiến Kaizen / Lean Six Sigma giúp tăng năng suất nhà máy 25%/năm.', '["Manufacturing / QA-QC", "Docker / Kubernetes", "Python", "Chinese HSK"]', '["English Ielts/Toeic"]', 5.0, '[{"criterion": "Tự động hóa Dây chuyền & Smart Factory", "weight": 0.35}, {"criterion": "Thực thi Lean Six Sigma & Kaizen", "weight": 0.35}, {"criterion": "Bảo trì Dự đoán (TPM)", "weight": 0.3}]', '{"must_have": 0.4, "semantic": 0.35, "experience": 0.25}', '[{"competency": "Tự động hóa Dây chuyền & Smart Factory", "question": "Hãy chia sẻ một dự án tích hợp Robot/AOI hoặc MES mà Anh/Chị chủ trì giúp cắt giảm nhân công thao tác thủ công và tăng Takt Time."}, {"competency": "Thực thi Lean Six Sigma & Kaizen", "question": "Anh/Chị làm thế nào để loại bỏ 7 lãng phí (Muda) trên mặt bằng xưởng và tính toán mức tiết kiệm chi phí hàng năm?"}, {"competency": "Bảo trì Dự đoán (TPM)", "question": "Cách Anh/Chị tổ chức đội ngũ kỹ sư bảo trì giảm thời gian dừng máy đột xuất (Unplanned Downtime) xuống dưới 1%?"}]', 0, '2026-10-17T14:01:09Z');
REPLACE INTO `jobs` (`id`, `org_id`, `title`, `department`, `location`, `employment_type`, `salary_range`, `language`, `report_languages`, `status`, `jd_text`, `must_have_skills`, `nice_to_have_skills`, `min_experience_years`, `rubric_config`, `scoring_weights`, `interview_questions`, `blind_mode`, `created_at`) VALUES ('job_10', 'org_vn_fdi_01', '[Quản lý Cao cấp] Giám đốc Quản lý Dự án Khu Đô thị & Công nghiệp (Project Director)', 'Bất động sản & Xây dựng Hạ tầng (Real Estate & Construction)', 'TP. Hồ Chí Minh / Long An', 'Full-time (Quản lý)', '80 - 135 Triệu VNĐ', 'vi', '["vi", "en", "ja", "ko", "zh", "th", "lo", "km"]', 'open', 'Chỉ đạo toàn diện tiến độ, ngân sách (trên 3.000 tỷ VNĐ), chất lượng thi công, an toàn lao động và nghiệm thu bàn giao dự án Khu đô thị phức hợp & Khu công nghiệp xanh.', '["Manufacturing / QA-QC", "Bridge SE / BA", "English Ielts/Toeic"]', '["B2B Sales / Telesales"]', 8.0, '[{"criterion": "Quản trị Tổng thầu & Ngân sách Dự án", "weight": 0.35}, {"criterion": "Quản lý Hợp đồng FIDIC & Đấu thầu", "weight": 0.35}, {"criterion": "Nghiệm thu & Bàn giao Đưa vào Vận hành", "weight": 0.3}]', '{"must_have": 0.4, "semantic": 0.35, "experience": 0.25}', '[{"competency": "Quản trị Tổng thầu & Ngân sách Dự án", "question": "Anh/Chị kiểm soát tiến độ, chất lượng và chống đội vốn (Cost Overrun) cho các đại dự án quy mô hàng nghìn tỷ đồng bằng cơ chế nào?"}, {"competency": "Quản lý Hợp đồng FIDIC & Đấu thầu", "question": "Kinh nghiệm của Anh/Chị trong việc xử lý các phát sinh biến động giá vật liệu và tranh chấp hợp đồng với tổng thầu quốc tế?"}, {"competency": "Nghiệm thu & Bàn giao Đưa vào Vận hành", "question": "Cách Anh/Chị phối hợp các cơ quan chức năng và tư vấn giám sát để hoàn tất nghiệm thu PCCC và đưa dự án vào khai thác đúng cam kết?"}]', 0, '2026-10-17T14:01:09Z');
REPLACE INTO `jobs` (`id`, `org_id`, `title`, `department`, `location`, `employment_type`, `salary_range`, `language`, `report_languages`, `status`, `jd_text`, `must_have_skills`, `nice_to_have_skills`, `min_experience_years`, `rubric_config`, `scoring_weights`, `interview_questions`, `blind_mode`, `created_at`) VALUES ('job_11', 'org_vn_fdi_01', '[Quản lý Cấp trung] Trưởng phòng Phát triển Dự án & Pháp lý Đầu tư (Project Development Manager)', 'Bất động sản & Xây dựng Hạ tầng (Real Estate & Construction)', 'Hà Nội / Hưng Yên', 'Full-time (Quản lý)', '48 - 75 Triệu VNĐ', 'vi', '["vi", "en", "ja", "ko", "zh", "th", "lo", "km"]', 'open', 'Chủ trì thủ tục pháp lý dự án bất động sản từ chấp thuận chủ trương đầu tư, quy hoạch 1/500, giao đất, tính tiền sử dụng đất đến giấy phép xây dựng theo Luật Đất đai và Luật Kinh doanh BĐS mới.', '["Bridge SE / BA", "B2B Sales / Telesales", "English Ielts/Toeic"]', '["Manufacturing / QA-QC"]', 5.0, '[{"criterion": "Thông hiểu Pháp lý Đầu tư & Quy hoạch", "weight": 0.35}, {"criterion": "Nghiên cứu Tiền khả thi (FS)", "weight": 0.35}, {"criterion": "Quan hệ Đối ngoại & Cơ quan Quản lý", "weight": 0.3}]', '{"must_have": 0.4, "semantic": 0.35, "experience": 0.25}', '[{"competency": "Thông hiểu Pháp lý Đầu tư & Quy hoạch", "question": "Anh/Chị đã từng tháo gỡ vướng mắc pháp lý quy hoạch 1/500 và nghĩa vụ tài chính đất đai cho những dự án nào để kịp tiến độ mở bán?"}, {"competency": "Nghiên cứu Tiền khả thi (FS)", "question": "Khi lập báo cáo nghiên cứu khả thi (Feasibility Study) cho quỹ đất mới, Anh/Chị phối hợp với khối Tài chính và Thiết kế ra sao?"}, {"competency": "Quan hệ Đối ngoại & Cơ quan Quản lý", "question": "Phương pháp làm việc chuyên nghiệp của Anh/Chị với các Sở Ban Ngành để rút ngắn thời gian thẩm định hồ sơ dự án?"}]', 0, '2026-10-17T14:01:09Z');
REPLACE INTO `jobs` (`id`, `org_id`, `title`, `department`, `location`, `employment_type`, `salary_range`, `language`, `report_languages`, `status`, `jd_text`, `must_have_skills`, `nice_to_have_skills`, `min_experience_years`, `rubric_config`, `scoring_weights`, `interview_questions`, `blind_mode`, `created_at`) VALUES ('job_12', 'org_vn_fdi_01', '[Quản lý Cao cấp] Giám đốc Kinh doanh & Phát triển Hệ thống Phân phối BĐS (Sales Director)', 'Bất động sản & Xây dựng Hạ tầng (Real Estate & Construction)', 'TP. Hồ Chí Minh', 'Full-time (Quản lý)', '70 - 125 Triệu VNĐ', 'vi', '["vi", "en", "ja", "ko", "zh", "th", "lo", "km"]', 'open', 'Xây dựng chiến lược bán hàng, quản trị mạng lưới 35 đại lý F1 và đội ngũ 200 chuyên viên kinh doanh In-house; chịu trách nhiệm chỉ tiêu doanh số (GMV) 5.000 tỷ VNĐ/năm.', '["B2B Sales / Telesales", "English Ielts/Toeic", "Bridge SE / BA"]', '["Chinese HSK"]', 7.0, '[{"criterion": "Chiến lược Mở bán & Quản trị Đại lý F1", "weight": 0.35}, {"criterion": "Chính sách Giá & Tài chính Khách hàng", "weight": 0.35}, {"criterion": "Xây dựng Đội ngũ Kinh doanh Tinh nhuệ", "weight": 0.3}]', '{"must_have": 0.4, "semantic": 0.35, "experience": 0.25}', '[{"competency": "Chiến lược Mở bán & Quản trị Đại lý F1", "question": "Anh/Chị đã từng tổ chức chiến dịch mở bán dự án đạt tỷ lệ hấp thụ (Absorption Rate) trên 85% trong bối cảnh thị trường cạnh tranh như thế nào?"}, {"competency": "Chính sách Giá & Tài chính Khách hàng", "question": "Cách Anh/Chị phối hợp với Ngân hàng thiết kế gói ân hạn nợ gốc và hỗ trợ lãi suất hấp dẫn người mua thực lẫn nhà đầu tư?"}, {"competency": "Xây dựng Đội ngũ Kinh doanh Tinh nhuệ", "question": "Anh/Chị thiết kế cơ chế hoa hồng và KPI như thế nào để thúc đẩy cả hệ thống đại lý lẫn đội ngũ bán hàng trực tiếp?"}]', 0, '2026-10-17T14:01:09Z');
REPLACE INTO `jobs` (`id`, `org_id`, `title`, `department`, `location`, `employment_type`, `salary_range`, `language`, `report_languages`, `status`, `jd_text`, `must_have_skills`, `nice_to_have_skills`, `min_experience_years`, `rubric_config`, `scoring_weights`, `interview_questions`, `blind_mode`, `created_at`) VALUES ('job_13', 'org_vn_fdi_01', '[Quản lý Cao cấp] Giám đốc Thương mại Đa kênh & E-Commerce (Omnichannel Commercial Director)', 'Bán lẻ, Thương mại Điện tử & FMCG (Retail & FMCG)', 'TP. Hồ Chí Minh', 'Full-time (Quản lý)', '75 - 130 Triệu VNĐ', 'vi', '["vi", "en", "ja", "ko", "zh", "th", "lo", "km"]', 'open', 'Chịu trách nhiệm toàn bộ P&L mảng Thương mại Đa kênh (Shopee Mall, TikTok Shop, Lazada, D2C Website và chuỗi 150 cửa hàng vật lý); tối ưu chuyển đổi bằng AI Personalization và quản trị danh mục hàng hóa.', '["B2B Sales / Telesales", "AI / LLM / RAG", "English Ielts/Toeic", "Bridge SE / BA"]', '["PostgreSQL / SQL"]', 7.0, '[{"criterion": "Tăng trưởng GMV Đa kênh & P&L", "weight": 0.35}, {"criterion": "Tích hợp O2O & Dữ liệu Khách hàng CDP", "weight": 0.35}, {"criterion": "Tối ưu Chi phí Quảng cáo (ROAS/CAC)", "weight": 0.3}]', '{"must_have": 0.4, "semantic": 0.35, "experience": 0.25}', '[{"competency": "Tăng trưởng GMV Đa kênh & P&L", "question": "Anh/Chị đã từng thúc đẩy tăng trưởng GMV kênh E-Commerce & Social Commerce (TikTok Shop/Shopee) trong khi vẫn giữ biên lợi nhuận ròng (EBITDA) dương như thế nào?"}, {"competency": "Tích hợp O2O & Dữ liệu Khách hàng CDP", "question": "Cách Anh/Chị đồng bộ tồn kho, giá bán và chương trình khách hàng thân thiết (Loyalty) giữa 150 cửa hàng Offline và kênh Online?"}, {"competency": "Tối ưu Chi phí Quảng cáo (ROAS/CAC)", "question": "Anh/Chị kiểm soát tỷ lệ chi phí Marketing/Doanh thu (CIR) và tăng giá trị vòng đời khách hàng (LTV) bằng những chỉ số nào?"}]', 0, '2026-10-17T14:01:09Z');
REPLACE INTO `jobs` (`id`, `org_id`, `title`, `department`, `location`, `employment_type`, `salary_range`, `language`, `report_languages`, `status`, `jd_text`, `must_have_skills`, `nice_to_have_skills`, `min_experience_years`, `rubric_config`, `scoring_weights`, `interview_questions`, `blind_mode`, `created_at`) VALUES ('job_14', 'org_vn_fdi_01', '[Quản lý Cấp trung] Trưởng phòng Tiếp thị Ngành hàng & Thương hiệu (Senior Brand & Trade Manager)', 'Bán lẻ, Thương mại Điện tử & FMCG (Retail & FMCG)', 'TP. Hồ Chí Minh', 'Full-time (Quản lý)', '45 - 72 Triệu VNĐ', 'vi', '["vi", "en", "ja", "ko", "zh", "th", "lo", "km"]', 'open', 'Hoạch định chiến lược thương hiệu, ra mắt sản phẩm mới (NPD) và thực thi chương trình Trade Marketing tại kênh GT/MT trên toàn quốc nhằm gia tăng thị phần (Market Share) ngành hàng FMCG.', '["B2B Sales / Telesales", "English Ielts/Toeic", "Bridge SE / BA"]', '["AI / LLM / RAG"]', 5.0, '[{"criterion": "Ra mắt Sản phẩm Mới & Tăng Thị phần", "weight": 0.35}, {"criterion": "Thực thi Trade Marketing Kênh GT/MT", "weight": 0.35}, {"criterion": "Quản trị Ngân sách Marketing (A&P)", "weight": 0.3}]', '{"must_have": 0.4, "semantic": 0.35, "experience": 0.25}', '[{"competency": "Ra mắt Sản phẩm Mới & Tăng Thị phần", "question": "Hãy chia sẻ một chiến dịch ra mắt sản phẩm FMCG thành công nhất mà Anh/Chị quản lý (thị phần Nielsen/Kantar tăng trưởng bao nhiêu %)?"}, {"competency": "Thực thi Trade Marketing Kênh GT/MT", "question": "Cách Anh/Chị tối ưu ngân sách trưng bày POSM và khuyến mãi tại điểm bán để đẩy sản lượng Sell-out thực tế?"}, {"competency": "Quản trị Ngân sách Marketing (A&P)", "question": "Anh/Chị phân bổ ngân sách giữa Branding dài hạn và kích cầu ngắn hạn như thế nào để đạt chỉ tiêu doanh thu quý?"}]', 0, '2026-10-17T14:01:09Z');
REPLACE INTO `jobs` (`id`, `org_id`, `title`, `department`, `location`, `employment_type`, `salary_range`, `language`, `report_languages`, `status`, `jd_text`, `must_have_skills`, `nice_to_have_skills`, `min_experience_years`, `rubric_config`, `scoring_weights`, `interview_questions`, `blind_mode`, `created_at`) VALUES ('job_15', 'org_vn_fdi_01', '[Quản lý Cấp trung] Trưởng phòng Vận hành Chuỗi Cửa hàng Bán lẻ Miền Nam (Retail Area Manager)', 'Bán lẻ, Thương mại Điện tử & FMCG (Retail & FMCG)', 'TP. Hồ Chí Minh / Đồng bằng Sông Cửu Long', 'Full-time (Quản lý)', '40 - 65 Triệu VNĐ', 'vi', '["vi", "en", "ja", "ko", "zh", "th", "lo", "km"]', 'open', 'Quản lý vận hành 60 cửa hàng bán lẻ hiện đại; chịu trách nhiệm doanh thu trên cùng diện tích (SSSG - Same Store Sales Growth), kiểm soát thất thoát hàng hóa (Shrinkage < 0.4%) và chuẩn mực dịch vụ khách hàng.', '["B2B Sales / Telesales", "Manufacturing / QA-QC", "QA / Testing"]', '["English Ielts/Toeic"]', 5.0, '[{"criterion": "Tăng trưởng Doanh thu Cửa hàng (SSSG)", "weight": 0.35}, {"criterion": "Kiểm soát Thất thoát & Vòng quay Tồn kho", "weight": 0.35}, {"criterion": "Tuyển dụng & Đào tạo Cửa hàng Trưởng", "weight": 0.3}]', '{"must_have": 0.4, "semantic": 0.35, "experience": 0.25}', '[{"competency": "Tăng trưởng Doanh thu Cửa hàng (SSSG)", "question": "Anh/Chị đã áp dụng những giải pháp trưng bày (Visual Merchandising) và bán chéo nào để nâng doanh thu trung bình trên mỗi hóa đơn (AOV)?"}, {"competency": "Kiểm soát Thất thoát & Vòng quay Tồn kho", "question": "Quy trình kiểm kê và chống thất thoát hàng hóa tại chuỗi 60 cửa hàng được Anh/Chị giám sát chặt chẽ ra sao?"}, {"competency": "Tuyển dụng & Đào tạo Cửa hàng Trưởng", "question": "Cách Anh/Chị xây dựng đội ngũ Cửa hàng trưởng kế cận và duy trì điểm hài lòng khách hàng (CSAT/NPS) trên 95%?"}]', 0, '2026-10-17T14:01:09Z');
REPLACE INTO `jobs` (`id`, `org_id`, `title`, `department`, `location`, `employment_type`, `salary_range`, `language`, `report_languages`, `status`, `jd_text`, `must_have_skills`, `nice_to_have_skills`, `min_experience_years`, `rubric_config`, `scoring_weights`, `interview_questions`, `blind_mode`, `created_at`) VALUES ('job_16', 'org_vn_fdi_01', '[Quản lý Cao cấp] Giám đốc Vận hành Hệ thống Bệnh viện Đa khoa Quốc tế (Hospital Operations Director)', 'Y tế, Dược phẩm & Chăm sóc Sức khỏe (Healthcare & Pharma)', 'TP. Hồ Chí Minh / Hà Nội', 'Full-time (Quản lý)', '80 - 135 Triệu VNĐ', 'vi', '["vi", "en", "ja", "ko", "zh", "th", "lo", "km"]', 'open', 'Điều hành toàn bộ hoạt động phi lâm sàng và dịch vụ bệnh nhân tại bệnh viện 400 giường tiêu chuẩn JCI; tối ưu hóa công suất phòng mổ/giường bệnh, hệ thống bệnh án điện tử HIS/EMR và hiệu quả tài chính.', '["Manufacturing / QA-QC", "QA / Testing", "English Ielts/Toeic", "Bridge SE / BA"]', '["AI / LLM / RAG"]', 8.0, '[{"criterion": "Vận hành Bệnh viện Chuẩn Quốc tế JCI", "weight": 0.35}, {"criterion": "Quản trị Tài chính & Công suất Giường bệnh", "weight": 0.35}, {"criterion": "Chuyển đổi Số Y tế (HIS/EMR/PACS)", "weight": 0.3}]', '{"must_have": 0.4, "semantic": 0.35, "experience": 0.25}', '[{"competency": "Vận hành Bệnh viện Chuẩn Quốc tế JCI", "question": "Anh/Chị đã từng điều hành quy trình vận hành bệnh viện đạt chuẩn JCI/ISO 15189 và rút ngắn thời gian chờ khám ngoại trú xuống bao nhiêu phút?"}, {"competency": "Quản trị Tài chính & Công suất Giường bệnh", "question": "Cách Anh/Chị tối ưu tỷ lệ lấp đầy giường nội trú, kiểm soát chi phí vật tư tiêu hao y tế và tăng biên lợi nhuận vận hành?"}, {"competency": "Chuyển đổi Số Y tế (HIS/EMR/PACS)", "question": "Kinh nghiệm của Anh/Chị trong việc triển khai Bệnh án điện tử (EMR) và ứng dụng AI hỗ trợ chẩn đoán/chăm sóc khách hàng y tế?"}]', 0, '2026-10-17T14:01:09Z');
REPLACE INTO `jobs` (`id`, `org_id`, `title`, `department`, `location`, `employment_type`, `salary_range`, `language`, `report_languages`, `status`, `jd_text`, `must_have_skills`, `nice_to_have_skills`, `min_experience_years`, `rubric_config`, `scoring_weights`, `interview_questions`, `blind_mode`, `created_at`) VALUES ('job_17', 'org_vn_fdi_01', '[Quản lý Cấp trung] Trưởng phòng Kinh doanh Dược phẩm Kênh Bệnh viện Toàn quốc (National ETC Sales Manager)', 'Y tế, Dược phẩm & Chăm sóc Sức khỏe (Healthcare & Pharma)', 'Hà Nội / TP. Hồ Chí Minh', 'Full-time (Quản lý)', '50 - 82 Triệu VNĐ', 'vi', '["vi", "en", "ja", "ko", "zh", "th", "lo", "km"]', 'open', 'Quản lý hoạt động đấu thầu thuốc kênh bệnh viện (ETC) và mạng lưới 45 Trình dược viên trên toàn quốc; đảm bảo tuân thủ quy định Luật Đấu thầu, Bộ Y tế và hoàn thành mục tiêu doanh số 450 tỷ VNĐ/năm.', '["B2B Sales / Telesales", "English Ielts/Toeic", "QA / Testing"]', '["Bridge SE / BA"]', 6.0, '[{"criterion": "Quản trị Đấu thầu Thuốc Kênh ETC", "weight": 0.35}, {"criterion": "Điều hành Đội ngũ Trình dược viên", "weight": 0.35}, {"criterion": "Tuân thủ Đạo đức Kinh doanh Dược (Compliance)", "weight": 0.3}]', '{"must_have": 0.4, "semantic": 0.35, "experience": 0.25}', '[{"competency": "Quản trị Đấu thầu Thuốc Kênh ETC", "question": "Anh/Chị xây dựng chiến lược danh mục thuốc tham gia thầu tập trung và thầu bệnh viện theo các thông tư mới của Bộ Y tế như thế nào?"}, {"competency": "Điều hành Đội ngũ Trình dược viên", "question": "Cách Anh/Chị sử dụng hệ thống CRM/SFE để giám sát hiệu suất viếng thăm và phát triển chuyên môn khoa học cho 45 Trình dược viên?"}, {"competency": "Tuân thủ Đạo đức Kinh doanh Dược (Compliance)", "question": "Anh/Chị kiểm soát rủi ro tuân thủ (Compliance & Anti-Bribery) trong các hội thảo khoa học và chương trình tiếp thị y khoa ra sao?"}]', 0, '2026-10-17T14:01:09Z');
REPLACE INTO `jobs` (`id`, `org_id`, `title`, `department`, `location`, `employment_type`, `salary_range`, `language`, `report_languages`, `status`, `jd_text`, `must_have_skills`, `nice_to_have_skills`, `min_experience_years`, `rubric_config`, `scoring_weights`, `interview_questions`, `blind_mode`, `created_at`) VALUES ('job_18', 'org_vn_fdi_01', '[Quản lý Cấp trung] Trưởng phòng Đăng ký Thuốc & Đảm bảo Chất lượng EU-GMP (Regulatory Affairs & QA Manager)', 'Y tế, Dược phẩm & Chăm sóc Sức khỏe (Healthcare & Pharma)', 'TP. Hồ Chí Minh / Bình Dương', 'Full-time (Quản lý)', '45 - 70 Triệu VNĐ', 'vi', '["vi", "en", "ja", "ko", "zh", "th", "lo", "km"]', 'open', 'Chịu trách nhiệm biên soạn, thẩm định hồ sơ đăng ký thuốc chuẩn ACTD/ICH trình Cục Quản lý Dược và duy trì hệ thống đảm bảo chất lượng nhà máy theo tiêu chuẩn EU-GMP / WHO-GMP.', '["QA / Testing", "Manufacturing / QA-QC", "English Ielts/Toeic"]', '["Bridge SE / BA"]', 5.0, '[{"criterion": "Đăng ký Thuốc & Hồ sơ ACTD/ICH", "weight": 0.35}, {"criterion": "Quản trị Hệ thống Chất lượng EU-GMP", "weight": 0.35}, {"criterion": "Cảnh giác Dược (Pharmacovigilance)", "weight": 0.3}]', '{"must_have": 0.4, "semantic": 0.35, "experience": 0.25}', '[{"competency": "Đăng ký Thuốc & Hồ sơ ACTD/ICH", "question": "Anh/Chị đã từng rút ngắn thời gian cấp Số đăng ký lưu hành (Visa thuốc) và xử lý các công văn bổ sung từ Cục Quản lý Dược như thế nào?"}, {"competency": "Quản trị Hệ thống Chất lượng EU-GMP", "question": "Kinh nghiệm của Anh/Chị trong việc chuẩn bị hồ sơ thẩm định quy trình, độ ổn định và tiếp đoàn thanh tra GMP quốc tế?"}, {"competency": "Cảnh giác Dược (Pharmacovigilance)", "question": "Quy trình giám sát phản ứng có hại của thuốc (ADR) và thu hồi lô sản phẩm khẩn cấp được Anh/Chị thiết lập ra sao?"}]', 0, '2026-10-17T14:01:09Z');
REPLACE INTO `jobs` (`id`, `org_id`, `title`, `department`, `location`, `employment_type`, `salary_range`, `language`, `report_languages`, `status`, `jd_text`, `must_have_skills`, `nice_to_have_skills`, `min_experience_years`, `rubric_config`, `scoring_weights`, `interview_questions`, `blind_mode`, `created_at`) VALUES ('job_19', 'org_vn_fdi_01', '[Quản lý Cao cấp] Giám đốc Chuỗi Cung ứng Toàn quốc (Head of End-to-End Supply Chain)', 'Logistics, Chuỗi Cung ứng & Xuất Nhập khẩu (Logistics & Supply Chain)', 'TP. Hồ Chí Minh', 'Full-time (Quản lý)', '75 - 130 Triệu VNĐ', 'vi', '["vi", "en", "ja", "ko", "zh", "th", "lo", "km"]', 'open', 'Điều hành chiến lược S&OP, dự báo nhu cầu bằng AI, mạng lưới 8 Trung tâm Phân phối (Fulfillment Centers), vận tải đa phương thức và xuất nhập khẩu; tối ưu tỷ lệ chi phí Logistics trên doanh thu giảm 18%.', '["Manufacturing / QA-QC", "PostgreSQL / SQL", "English Ielts/Toeic", "Bridge SE / BA"]', '["AI / LLM / RAG"]', 8.0, '[{"criterion": "Hoạch định S&OP & Tối ưu Tồn kho", "weight": 0.35}, {"criterion": "Thiết kế Mạng lưới Trung tâm Phân phối", "weight": 0.35}, {"criterion": "Quản trị Rủi ro Đứt gãy Chuỗi Cung ứng", "weight": 0.3}]', '{"must_have": 0.4, "semantic": 0.35, "experience": 0.25}', '[{"competency": "Hoạch định S&OP & Tối ưu Tồn kho", "question": "Anh/Chị đã từng điều hành quy trình S&OP giúp nâng tỷ lệ đáp ứng đơn hàng (OTIF) lên trên 98% đồng thời giảm số ngày tồn kho (DOH) như thế nào?"}, {"competency": "Thiết kế Mạng lưới Trung tâm Phân phối", "question": "Cách Anh/Chị ứng dụng hệ thống WMS/TMS tự động hóa để tối ưu năng suất lấy hàng và chi phí giao hàng chặng cuối (Last-mile)?"}, {"competency": "Quản trị Rủi ro Đứt gãy Chuỗi Cung ứng", "question": "Khi giá cước vận tải biển tăng đột biến hoặc thiếu hụt container xuất khẩu, Anh/Chị kích hoạt phương án dự phòng nào?"}]', 0, '2026-10-17T14:01:09Z');
REPLACE INTO `jobs` (`id`, `org_id`, `title`, `department`, `location`, `employment_type`, `salary_range`, `language`, `report_languages`, `status`, `jd_text`, `must_have_skills`, `nice_to_have_skills`, `min_experience_years`, `rubric_config`, `scoring_weights`, `interview_questions`, `blind_mode`, `created_at`) VALUES ('job_20', 'org_vn_fdi_01', '[Quản lý Cấp trung] Trưởng phòng Khai thác Kho vận & Vận tải Quốc tế (Logistics & Fleet Operations Manager)', 'Logistics, Chuỗi Cung ứng & Xuất Nhập khẩu (Logistics & Supply Chain)', 'Hải Phòng / Bình Dương', 'Full-time (Quản lý)', '42 - 66 Triệu VNĐ', 'vi', '["vi", "en", "ja", "ko", "zh", "th", "lo", "km"]', 'open', 'Quản lý vận hành hệ thống kho ngoại quan 50.000 m2 và đội xe đầu kéo container 120 chiếc; tối ưu lộ trình vận tải, định mức nhiên liệu, thông quan hải quan điện tử VNACCS/VCIS.', '["Manufacturing / QA-QC", "QA / Testing", "English Ielts/Toeic"]', '["Chinese HSK"]', 5.0, '[{"criterion": "Vận hành Kho Ngoại quan & WMS", "weight": 0.35}, {"criterion": "Quản trị Đội xe & Tối ưu Nhiên liệu", "weight": 0.35}, {"criterion": "Thông quan Hải quan & Hàng Xuất Nhập khẩu", "weight": 0.3}]', '{"must_have": 0.4, "semantic": 0.35, "experience": 0.25}', '[{"competency": "Vận hành Kho Ngoại quan & WMS", "question": "Anh/Chị quản lý độ chính xác tồn kho (Inventory Accuracy >= 99.9%) và tối ưu diện tích lưu trữ trên mỗi pallet tại kho lớn như thế nào?"}, {"competency": "Quản trị Đội xe & Tối ưu Nhiên liệu", "question": "Cách Anh/Chị giám sát GPS/IoT đội xe 120 đầu kéo để tăng hệ số quay vòng chuyến và giảm chi phí nhiên liệu/bảo dưỡng?"}, {"competency": "Thông quan Hải quan & Hàng Xuất Nhập khẩu", "question": "Kinh nghiệm xử lý các lô hàng luồng đỏ, kiểm tra chuyên ngành và hoàn thuế xuất nhập khẩu nhanh chóng, đúng luật?"}]', 0, '2026-10-17T14:01:09Z');
REPLACE INTO `jobs` (`id`, `org_id`, `title`, `department`, `location`, `employment_type`, `salary_range`, `language`, `report_languages`, `status`, `jd_text`, `must_have_skills`, `nice_to_have_skills`, `min_experience_years`, `rubric_config`, `scoring_weights`, `interview_questions`, `blind_mode`, `created_at`) VALUES ('job_21', 'org_vn_fdi_01', '[Quản lý Cấp trung] Trưởng phòng Mua hàng Chiến lược & Phát triển Nhà cung cấp (Strategic Procurement Manager)', 'Logistics, Chuỗi Cung ứng & Xuất Nhập khẩu (Logistics & Supply Chain)', 'Hà Nội / Bắc Ninh', 'Full-time (Quản lý)', '45 - 70 Triệu VNĐ', 'vi', '["vi", "en", "ja", "ko", "zh", "th", "lo", "km"]', 'open', 'Phụ trách ngân sách thu mua nguyên vật liệu và thiết bị trị giá 1.500 tỷ VNĐ/năm từ thị trường Việt Nam, Trung Quốc, Nhật Bản, Hàn Quốc; đàm phán Cost Saving 8-12%/năm và nội địa hóa chuỗi cung ứng.', '["B2B Sales / Telesales", "English Ielts/Toeic", "Chinese HSK", "Japanese N2/N3"]', '["Korean TOPIK"]', 5.0, '[{"criterion": "Chiến lược Đàm phán & Tiết giảm Chi phí", "weight": 0.35}, {"criterion": "Đa dạng hóa & Nội địa hóa Nguồn cung", "weight": 0.35}, {"criterion": "Minh bạch Đấu thầu & Quản trị Hợp đồng", "weight": 0.3}]', '{"must_have": 0.4, "semantic": 0.35, "experience": 0.25}', '[{"competency": "Chiến lược Đàm phán & Tiết giảm Chi phí", "question": "Anh/Chị áp dụng mô hình Should-Cost và TCO (Total Cost of Ownership) để đàm phán giảm giá mua nguyên vật liệu đạt bao nhiêu tỷ đồng/năm?"}, {"competency": "Đa dạng hóa & Nội địa hóa Nguồn cung", "question": "Cách Anh/Chị tìm kiếm, đánh giá và phát triển các nhà cung cấp nội địa Việt Nam đạt chuẩn thay thế nguồn hàng nhập khẩu?"}, {"competency": "Minh bạch Đấu thầu & Quản trị Hợp đồng", "question": "Anh/Chị xây dựng quy trình e-Procurement và kiểm soát xung đột lợi ích trong đấu thầu mua sắm như thế nào?"}]', 0, '2026-10-17T14:01:09Z');
REPLACE INTO `jobs` (`id`, `org_id`, `title`, `department`, `location`, `employment_type`, `salary_range`, `language`, `report_languages`, `status`, `jd_text`, `must_have_skills`, `nice_to_have_skills`, `min_experience_years`, `rubric_config`, `scoring_weights`, `interview_questions`, `blind_mode`, `created_at`) VALUES ('job_22', 'org_vn_fdi_01', '[Quản lý Cao cấp] Giám đốc Phát triển Dự án Điện Gió, Điện Mặt trời & DPPA (Renewable Energy Director)', 'Năng lượng Tái tạo & Môi trường ESG (Renewable Energy & ESG)', 'TP. Hồ Chí Minh / Ninh Thuận', 'Full-time (Quản lý)', '85 - 145 Triệu VNĐ', 'vi', '["vi", "en", "ja", "ko", "zh", "th", "lo", "km"]', 'open', 'Chỉ đạo phát triển danh mục dự án Điện gió, Điện mặt trời áp mái khu công nghiệp và cơ chế Mua bán điện trực tiếp (DPPA) quy mô 300 MW theo Quy hoạch Điện VIII.', '["Manufacturing / QA-QC", "English Ielts/Toeic", "Bridge SE / BA", "B2B Sales / Telesales"]', '["Chinese HSK"]', 8.0, '[{"criterion": "Phát triển Dự án Năng lượng & Cơ chế DPPA", "weight": 0.35}, {"criterion": "Quản trị EPC & Tài chính Dự án Năng lượng", "weight": 0.35}, {"criterion": "Tuân thủ Quy hoạch Điện VIII", "weight": 0.3}]', '{"must_have": 0.4, "semantic": 0.35, "experience": 0.25}', '[{"competency": "Phát triển Dự án Năng lượng & Cơ chế DPPA", "question": "Anh/Chị đã từng dẫn dắt việc đàm phán hợp đồng mua bán điện trực tiếp (DPPA) với các nhà máy FDI lớn và đấu nối lưới điện quốc gia như thế nào?"}, {"competency": "Quản trị EPC & Tài chính Dự án Năng lượng", "question": "Cách Anh/Chị tối ưu suất đầu tư (CAPEX/MWp) và làm việc với các định chế tài chính xanh (ADB, IFC) để thu xếp vốn dự án?"}, {"competency": "Tuân thủ Quy hoạch Điện VIII", "question": "Kinh nghiệm hoàn thiện hồ sơ pháp lý năng lượng, thỏa thuận đấu nối EVN và giấy phép hoạt động điện lực đúng tiến độ COD?"}]', 0, '2026-10-17T14:01:09Z');
REPLACE INTO `jobs` (`id`, `org_id`, `title`, `department`, `location`, `employment_type`, `salary_range`, `language`, `report_languages`, `status`, `jd_text`, `must_have_skills`, `nice_to_have_skills`, `min_experience_years`, `rubric_config`, `scoring_weights`, `interview_questions`, `blind_mode`, `created_at`) VALUES ('job_23', 'org_vn_fdi_01', '[Quản lý Cấp trung] Trưởng phòng Kỹ thuật Vận hành Nhà máy Điện & Hệ thống BESS (O&M Engineering Manager)', 'Năng lượng Tái tạo & Môi trường ESG (Renewable Energy & ESG)', 'Bình Thuận / Gia Lai', 'Full-time (Quản lý)', '48 - 75 Triệu VNĐ', 'vi', '["vi", "en", "ja", "ko", "zh", "th", "lo", "km"]', 'open', 'Quản lý vận hành và bảo dưỡng (O&M) cụm nhà máy điện mặt trời & điện gió 150 MW kèm hệ thống lưu trữ năng lượng pin (BESS); đảm bảo hệ số khả dụng (Availability Factor) >= 99.2%.', '["Manufacturing / QA-QC", "QA / Testing", "English Ielts/Toeic"]', '["Python"]', 5.0, '[{"criterion": "Vận hành SCADA & Tối ưu Sản lượng Phát", "weight": 0.35}, {"criterion": "An toàn Điện Cao thế & Trạm 110kV/220kV", "weight": 0.35}, {"criterion": "Tích hợp Hệ thống Lưu trữ BESS", "weight": 0.3}]', '{"must_have": 0.4, "semantic": 0.35, "experience": 0.25}', '[{"competency": "Vận hành SCADA & Tối ưu Sản lượng Phát", "question": "Anh/Chị sử dụng dữ liệu SCADA và phân tích nhiệt ảnh (Thermography) để nâng cao tỷ số hiệu suất PR (Performance Ratio) của nhà máy điện như thế nào?"}, {"competency": "An toàn Điện Cao thế & Trạm 110kV/220kV", "question": "Quy trình an toàn LOTO và bảo trì định kỳ trạm biến áp 110kV/220kV được Anh/Chị kiểm soát ra sao để tránh sự cố lưới?"}, {"competency": "Tích hợp Hệ thống Lưu trữ BESS", "question": "Kinh nghiệm của Anh/Chị trong việc vận hành hệ thống lưu trữ năng lượng BESS nhằm giảm cắt giảm công suất (Curtailment)?"}]', 0, '2026-10-17T14:01:09Z');
REPLACE INTO `jobs` (`id`, `org_id`, `title`, `department`, `location`, `employment_type`, `salary_range`, `language`, `report_languages`, `status`, `jd_text`, `must_have_skills`, `nice_to_have_skills`, `min_experience_years`, `rubric_config`, `scoring_weights`, `interview_questions`, `blind_mode`, `created_at`) VALUES ('job_24', 'org_vn_fdi_01', '[Quản lý Cấp trung] Trưởng phòng Quản trị Phát triển Bền vững & Kiểm kê Khí nhà kính (ESG & Carbon Manager)', 'Năng lượng Tái tạo & Môi trường ESG (Renewable Energy & ESG)', 'TP. Hồ Chí Minh / Hà Nội', 'Full-time (Quản lý)', '45 - 72 Triệu VNĐ', 'vi', '["vi", "en", "ja", "ko", "zh", "th", "lo", "km"]', 'open', 'Xây dựng chiến lược Net-Zero, thực hiện kiểm kê khí nhà kính phạm vi Scope 1, 2, 3 theo ISO 14064, lập Báo cáo Phát triển Bền vững chuẩn GRI/ISSB và đối ứng cơ chế CBAM châu Âu.', '["QA / Testing", "Manufacturing / QA-QC", "English Ielts/Toeic", "Bridge SE / BA"]', '["PostgreSQL / SQL"]', 5.0, '[{"criterion": "Kiểm kê Khí nhà kính ISO 14064 & CBAM", "weight": 0.35}, {"criterion": "Báo cáo ESG Chuẩn Quốc tế GRI & Tín chỉ Carbon", "weight": 0.35}, {"criterion": "Tích hợp ESG vào Chuỗi Cung ứng", "weight": 0.3}]', '{"must_have": 0.4, "semantic": 0.35, "experience": 0.25}', '[{"competency": "Kiểm kê Khí nhà kính ISO 14064 & CBAM", "question": "Anh/Chị đã từng triển khai kiểm kê phát thải Scope 1, 2, 3 và xây dựng lộ trình giảm phát thải đáp ứng tiêu chuẩn xuất khẩu CBAM châu Âu như thế nào?"}, {"competency": "Báo cáo ESG Chuẩn Quốc tế GRI & Tín chỉ Carbon", "question": "Kinh nghiệm của Anh/Chị trong việc đăng ký chứng chỉ năng lượng tái tạo (I-REC), giao dịch tín chỉ Carbon và huy động Tín dụng Xanh?"}, {"competency": "Tích hợp ESG vào Chuỗi Cung ứng", "question": "Cách Anh/Chị thiết lập bộ tiêu chí đánh giá ESG cho các nhà máy và nhà cung cấp trong toàn tập đoàn?"}]', 0, '2026-10-17T14:01:09Z');
REPLACE INTO `jobs` (`id`, `org_id`, `title`, `department`, `location`, `employment_type`, `salary_range`, `language`, `report_languages`, `status`, `jd_text`, `must_have_skills`, `nice_to_have_skills`, `min_experience_years`, `rubric_config`, `scoring_weights`, `interview_questions`, `blind_mode`, `created_at`) VALUES ('job_25', 'org_vn_fdi_01', '[Quản lý Cao cấp] Tổng Quản lý Khu Nghỉ dưỡng 5 Sao Quốc tế (General Manager - Luxury Resort)', 'Du lịch, Khách sạn & Nghỉ dưỡng 5 Sao (Hospitality & Luxury Resorts)', 'Phú Quốc / Đà Nẵng / Nha Trang', 'Full-time (Quản lý)', '85 - 150 Triệu VNĐ', 'vi', '["vi", "en", "ja", "ko", "zh", "th", "lo", "km"]', 'open', 'Điều hành toàn diện quần thể Resort & Villa 5 sao quy mô 350 phòng và trung tâm hội nghị MICE; chịu trách nhiệm chỉ số GOP (Gross Operating Profit), RevPAR, điểm đánh giá khách hàng quốc tế và quản trị 450 nhân sự.', '["B2B Sales / Telesales", "English Ielts/Toeic", "Korean TOPIK", "QA / Testing"]', '["Chinese HSK", "Japanese N2/N3"]', 8.0, '[{"criterion": "Điều hành P&L & Tối ưu Chỉ số GOP / RevPAR", "weight": 0.35}, {"criterion": "Quản trị Chất lượng Dịch vụ Xa xỉ (Luxury Standards)", "weight": 0.35}, {"criterion": "Lãnh đạo Đa văn hóa & Giữ chân Nhân sự", "weight": 0.3}]', '{"must_have": 0.4, "semantic": 0.35, "experience": 0.25}', '[{"competency": "Điều hành P&L & Tối ưu Chỉ số GOP / RevPAR", "question": "Anh/Chị đã từng nâng tỷ lệ lấp đầy (Occupancy Rate), giá phòng bình quân (ADR) và biên lợi nhuận GOP tại Resort 5 sao lên mức nào?"}, {"competency": "Quản trị Chất lượng Dịch vụ Xa xỉ (Luxury Standards)", "question": "Cách Anh/Chị duy trì điểm đánh giá trên Booking/TripAdvisor >= 9.4 và thiết kế trải nghiệm cá nhân hóa cho khách VIP quốc tế?"}, {"competency": "Lãnh đạo Đa văn hóa & Giữ chân Nhân sự", "question": "Anh/Chị xây dựng văn hóa dịch vụ hiếu khách và đào tạo đội ngũ 450 nhân viên tại các điểm đến nghỉ dưỡng như thế nào?"}]', 0, '2026-10-17T14:01:09Z');
REPLACE INTO `jobs` (`id`, `org_id`, `title`, `department`, `location`, `employment_type`, `salary_range`, `language`, `report_languages`, `status`, `jd_text`, `must_have_skills`, `nice_to_have_skills`, `min_experience_years`, `rubric_config`, `scoring_weights`, `interview_questions`, `blind_mode`, `created_at`) VALUES ('job_26', 'org_vn_fdi_01', '[Quản lý Cao cấp] Giám đốc Kinh doanh & Quản trị Doanh thu Hệ thống Khách sạn (Director of Sales & Revenue)', 'Du lịch, Khách sạn & Nghỉ dưỡng 5 Sao (Hospitality & Luxury Resorts)', 'TP. Hồ Chí Minh / Đà Nẵng', 'Full-time (Quản lý)', '58 - 95 Triệu VNĐ', 'vi', '["vi", "en", "ja", "ko", "zh", "th", "lo", "km"]', 'open', 'Hoạch định chiến lược giá linh hoạt (Dynamic Pricing), quản trị kênh phân phối OTA, TA/TO quốc tế (Hàn Quốc, Nhật Bản, Trung Quốc, Âu Mỹ, Ấn Độ) và mảng khách đoàn MICE doanh nghiệp.', '["B2B Sales / Telesales", "English Ielts/Toeic", "Korean TOPIK", "Chinese HSK"]', '["Japanese N2/N3"]', 6.0, '[{"criterion": "Quản trị Doanh thu (Revenue Management)", "weight": 0.35}, {"criterion": "Mở rộng Thị trường Khách Quốc tế & MICE", "weight": 0.35}, {"criterion": "Tối ưu Chi phí Hoa hồng Kênh Phân phối", "weight": 0.3}]', '{"must_have": 0.4, "semantic": 0.35, "experience": 0.25}', '[{"competency": "Quản trị Doanh thu (Revenue Management)", "question": "Anh/Chị áp dụng thuật toán Dynamic Pricing và phân bổ quỹ phòng giữa kênh OTA, lữ hành quốc tế (Series Booking) và đặt phòng trực tiếp ra sao?"}, {"competency": "Mở rộng Thị trường Khách Quốc tế & MICE", "question": "Anh/Chị đã ký kết hợp đồng chiến lược với các hãng lữ hành lớn tại Hàn Quốc, Nhật Bản, châu Âu mang về doanh thu bao nhiêu tỷ đồng/năm?"}, {"competency": "Tối ưu Chi phí Hoa hồng Kênh Phân phối", "question": "Giải pháp của Anh/Chị để tăng tỷ trọng đặt phòng trực tiếp qua Website (Direct Booking) nhằm giảm chi phí hoa hồng OTA?"}]', 0, '2026-10-17T14:01:09Z');
REPLACE INTO `jobs` (`id`, `org_id`, `title`, `department`, `location`, `employment_type`, `salary_range`, `language`, `report_languages`, `status`, `jd_text`, `must_have_skills`, `nice_to_have_skills`, `min_experience_years`, `rubric_config`, `scoring_weights`, `interview_questions`, `blind_mode`, `created_at`) VALUES ('job_27', 'org_vn_fdi_01', '[Quản lý Cấp trung] Trưởng khối Ẩm thực & Dịch vụ Lưu trú Cao cấp (F&B and Rooms Division Manager)', 'Du lịch, Khách sạn & Nghỉ dưỡng 5 Sao (Hospitality & Luxury Resorts)', 'Đà Nẵng / Hội An', 'Full-time (Quản lý)', '42 - 65 Triệu VNĐ', 'vi', '["vi", "en", "ja", "ko", "zh", "th", "lo", "km"]', 'open', 'Quản lý vận hành 4 nhà hàng chuyên đề, Sky Bar, dịch vụ tiệc hội nghị (Banquet) và khối Tiền sảnh - Buồng phòng; kiểm soát Food Cost dưới 28% và đảm bảo tiêu chuẩn vệ sinh an toàn thực phẩm HACCP.', '["QA / Testing", "Manufacturing / QA-QC", "English Ielts/Toeic"]', '["B2B Sales / Telesales"]', 5.0, '[{"criterion": "Tối ưu Doanh thu F&B & Kiểm soát Food Cost", "weight": 0.35}, {"criterion": "Tiêu chuẩn HACCP & Vận hành Đại tiệc MICE", "weight": 0.35}, {"criterion": "Phối hợp Liên bộ phận Lưu trú & Ẩm thực", "weight": 0.3}]', '{"must_have": 0.4, "semantic": 0.35, "experience": 0.25}', '[{"competency": "Tối ưu Doanh thu F&B & Kiểm soát Food Cost", "question": "Anh/Chị thiết kế thực đơn (Menu Engineering) và kiểm soát định lượng nguyên liệu như thế nào để giữ Food & Beverage Cost ở mức tối ưu?"}, {"competency": "Tiêu chuẩn HACCP & Vận hành Đại tiệc MICE", "question": "Kinh nghiệm của Anh/Chị khi điều phối các sự kiện Gala Dinner từ 500 - 1.000 khách đảm bảo tốc độ phục vụ và an toàn thực phẩm tuyệt đối?"}, {"competency": "Phối hợp Liên bộ phận Lưu trú & Ẩm thực", "question": "Cách Anh/Chị xử lý tức thời các tình huống khiếu nại của khách hàng để biến trải nghiệm chưa hài lòng thành sự gắn kết thương hiệu?"}]', 0, '2026-10-17T14:01:09Z');
REPLACE INTO `jobs` (`id`, `org_id`, `title`, `department`, `location`, `employment_type`, `salary_range`, `language`, `report_languages`, `status`, `jd_text`, `must_have_skills`, `nice_to_have_skills`, `min_experience_years`, `rubric_config`, `scoring_weights`, `interview_questions`, `blind_mode`, `created_at`) VALUES ('job_28', 'org_vn_fdi_01', '[Quản lý Cao cấp] Giám đốc Điều hành Hệ thống Trường Liên cấp Song ngữ Quốc tế (School Operations Director)', 'Giáo dục Quốc tế & Công nghệ Giáo dục (Education & EdTech)', 'Hà Nội / TP. Hồ Chí Minh', 'Full-time (Quản lý)', '70 - 120 Triệu VNĐ', 'vi', '["vi", "en", "ja", "ko", "zh", "th", "lo", "km"]', 'open', 'Điều hành toàn bộ hoạt động vận hành, tuyển sinh, tài chính, dịch vụ học sinh và kiểm định quốc tế CIS/IB cho cụm 3 cơ sở trường liên cấp quy mô 4.500 học sinh và 380 giáo viên trong và ngoài nước.', '["B2B Sales / Telesales", "English Ielts/Toeic", "QA / Testing", "Bridge SE / BA"]', '["AI / LLM / RAG"]', 7.0, '[{"criterion": "Điều hành Vận hành Trường học & Kiểm định CIS/IB", "weight": 0.35}, {"criterion": "Chiến lược Tuyển sinh & Giữ chân Học sinh", "weight": 0.35}, {"criterion": "Quản trị Đội ngũ Giáo viên Quốc tế & Nội địa", "weight": 0.3}]', '{"must_have": 0.4, "semantic": 0.35, "experience": 0.25}', '[{"competency": "Điều hành Vận hành Trường học & Kiểm định CIS/IB", "question": "Anh/Chị đã từng dẫn dắt hệ thống trường đạt chứng nhận kiểm định quốc tế CIS/Cognia và tối ưu hiệu quả vận hành cơ sở vật chất như thế nào?"}, {"competency": "Chiến lược Tuyển sinh & Giữ chân Học sinh", "question": "Cách Anh/Chị nâng tỷ lệ tái ghi danh hàng năm (Student Retention Rate) đạt trên 94% và hoàn thành chỉ tiêu tuyển sinh đầu cấp?"}, {"competency": "Quản trị Đội ngũ Giáo viên Quốc tế & Nội địa", "question": "Anh/Chị xây dựng môi trường làm việc và khung đánh giá chất lượng giảng dạy cho 380 giáo viên đa quốc tịch ra sao?"}]', 0, '2026-10-17T14:01:09Z');
REPLACE INTO `jobs` (`id`, `org_id`, `title`, `department`, `location`, `employment_type`, `salary_range`, `language`, `report_languages`, `status`, `jd_text`, `must_have_skills`, `nice_to_have_skills`, `min_experience_years`, `rubric_config`, `scoring_weights`, `interview_questions`, `blind_mode`, `created_at`) VALUES ('job_29', 'org_vn_fdi_01', '[Quản lý Cấp trung] Trưởng phòng Phát triển Chương trình Học thuật & Khảo thí (Academic & Curriculum Manager)', 'Giáo dục Quốc tế & Công nghệ Giáo dục (Education & EdTech)', 'TP. Hồ Chí Minh', 'Full-time (Quản lý)', '42 - 68 Triệu VNĐ', 'vi', '["vi", "en", "ja", "ko", "zh", "th", "lo", "km"]', 'open', 'Chủ trì thiết kế khung chương trình đào tạo chuẩn Cambridge / IELTS / STEAM tích hợp trợ lý học tập AI; quản lý chất lượng khảo thí, đào tạo giáo viên và đo lường đầu ra học thuật của học viên.', '["English Ielts/Toeic", "QA / Testing", "AI / LLM / RAG"]', '["Japanese N2/N3", "Korean TOPIK"]', 5.0, '[{"criterion": "Thiết kế Chương trình Chuẩn Quốc tế & AI", "weight": 0.35}, {"criterion": "Kiểm định Chất lượng Giảng dạy & Khảo thí", "weight": 0.35}, {"criterion": "Nâng cao Tỷ lệ Hoàn thành Khóa học", "weight": 0.3}]', '{"must_have": 0.4, "semantic": 0.35, "experience": 0.25}', '[{"competency": "Thiết kế Chương trình Chuẩn Quốc tế & AI", "question": "Anh/Chị tích hợp phương pháp giảng dạy cá nhân hóa bằng AI (Adaptive Learning) vào khung chương trình Cambridge/IELTS như thế nào để tăng điểm đầu ra?"}, {"competency": "Kiểm định Chất lượng Giảng dạy & Khảo thí", "question": "Quy trình dự giờ, đánh giá năng lực sư phạm và chuẩn hóa ngân hàng đề thi được Anh/Chị triển khai ra sao?"}, {"competency": "Nâng cao Tỷ lệ Hoàn thành Khóa học", "question": "Những chỉ số học thuật nào được Anh/Chị theo dõi hàng tuần để hỗ trợ kịp thời các học viên có nguy cơ chậm tiến độ?"}]', 0, '2026-10-17T14:01:09Z');
REPLACE INTO `jobs` (`id`, `org_id`, `title`, `department`, `location`, `employment_type`, `salary_range`, `language`, `report_languages`, `status`, `jd_text`, `must_have_skills`, `nice_to_have_skills`, `min_experience_years`, `rubric_config`, `scoring_weights`, `interview_questions`, `blind_mode`, `created_at`) VALUES ('job_30', 'org_vn_fdi_01', '[Quản lý Cao cấp] Giám đốc Sản phẩm & Tăng trưởng Nền tảng EdTech AI (Head of EdTech Product & Growth)', 'Giáo dục Quốc tế & Công nghệ Giáo dục (Education & EdTech)', 'Hà Nội / TP. Hồ Chí Minh', 'Full-time (Quản lý)', '65 - 110 Triệu VNĐ', 'vi', '["vi", "en", "ja", "ko", "zh", "th", "lo", "km"]', 'open', 'Dẫn dắt chiến lược sản phẩm và tăng trưởng người dùng cho nền tảng học ngoại ngữ & kỹ năng số bằng AI (500.000 người dùng trả phí tại Việt Nam & Đông Nam Á); tối ưu tỷ lệ giữ chân D30, LTV/CAC và doanh thu gói thuê bao (ARR).', '["AI / LLM / RAG", "React / Next.js", "B2B Sales / Telesales", "English Ielts/Toeic"]', '["Python", "PostgreSQL / SQL"]', 6.0, '[{"criterion": "Chiến lược Sản phẩm AI EdTech & Gamification", "weight": 0.35}, {"criterion": "Tăng trưởng Thuê bao Trả phí (PLG & B2B2C)", "weight": 0.35}, {"criterion": "Mở rộng Thị trường B2B Doanh nghiệp & Trường học", "weight": 0.3}]', '{"must_have": 0.4, "semantic": 0.35, "experience": 0.25}', '[{"competency": "Chiến lược Sản phẩm AI EdTech & Gamification", "question": "Anh/Chị đã từng thiết kế tính năng AI Gia sư giọng nói và cơ chế Gamification giúp tăng tỷ lệ người dùng hoạt động hàng ngày (DAU/MAU) lên bao nhiêu %?"}, {"competency": "Tăng trưởng Thuê bao Trả phí (PLG & B2B2C)", "question": "Cách Anh/Chị tối ưu phễu chuyển đổi từ học thử miễn phí sang gói trả phí năm (Annual Subscription) và giảm tỷ lệ rời bỏ (Churn Rate)?"}, {"competency": "Mở rộng Thị trường B2B Doanh nghiệp & Trường học", "question": "Kinh nghiệm của Anh/Chị trong việc đóng gói giải pháp EdTech bán cho khối Doanh nghiệp (Corporate L&D) và Hệ thống Trường phổ thông?"}]', 0, '2026-10-17T14:01:09Z');
