REPLACE INTO `system_notifications` (`id`, `category`, `severity`, `title`, `message`, `action_source`, `entity_id`, `steps_json`, `is_read`, `created_at`) VALUES ('NOTIF-AI-01', 'ai_evaluation', 'success', '🤖 AI Best-Fit Engine đã hoàn tất xếp hạng 30 vị trí', 'Đã đối chiếu 4 trụ cột CV + Phỏng vấn STAR qua cổng motapis.com/v1. Độ tương đồng bình quân đạt 88.4%.', 'AI Best-Fit Comparative Engine', 'job_01', '["Quét dữ liệu CV & Phỏng vấn STAR từ SQLite", "Chấm điểm 4 trụ cột (Kỹ năng 40% • Ngữ nghĩa 30% • Kinh nghiệm 20% • Định dạng 10%)", "Xếp hạng Top 1 Best-Fit và đồng bộ Kanban ATS"]', 0, '2026-10-19T08:30:00Z');
REPLACE INTO `system_notifications` (`id`, `category`, `severity`, `title`, `message`, `action_source`, `entity_id`, `steps_json`, `is_read`, `created_at`) VALUES ('NOTIF-SEC-02', 'security_alert', 'warning', '🛡️ Cảnh báo Tường lửa AI: Chặn Prompt Injection trong CV', 'Hệ thống phát hiện 01 hồ sơ chứa chỉ thị ẩn \'Ignore all previous instructions\'. Đã cô lập & yêu cầu HR duyệt thủ công.', 'AI Prompt Firewall & PII Masking', 'app_04', '["Phát hiện mẫu tấn công Prompt Injection trong lớp văn bản ẩn PDF", "Gắn cờ cảnh báo đỏ prompt_injection_flagged = 1", "Chuyển trạng thái sang Human-in-the-loop Review"]', 0, '2026-10-19T09:05:00Z');
