REPLACE INTO `rbac_roles` (`id`, `code`, `name`, `badge_color`, `description`, `data_scope`, `allowed_tabs_json`, `permissions_json`, `is_system`, `status`, `updated_at`) VALUES ('chro_director', 'CHRO_DIRECTOR', '🏛️ Giám đốc Nhân sự Tập đoàn (CHRO / HR Head)', 'blue', 'Phê duyệt định biên nhân sự, quyết định thư mời nhận việc (Offer), giám sát SLA, xem PII gốc và điều hành toàn bộ quy trình tuyển dụng.', 'OWN_TENANT', '["dashboard", "requisitions", "jobs", "pipeline", "interview", "assessment", "compare", "offers", "strategy", "careers", "users", "rbac", "ads", "categories"]', '{"can_create": true, "can_edit": true, "can_delete": true, "can_approve": true, "can_ai_evaluate": true, "can_view_pii": true, "can_export": true, "can_manage_rbac": true}', 1, 'active', '2026-10-19T04:23:47Z');
